def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)
    adv_gap = batch['advantage_gap']
    margin = float(extra.get('margin', 0.5))

    diff = ops.sub(lpw, lpl)  # difference in log probabilities
    hinge_loss = ops.max(ops.sub(margin, diff), ops.zeros_like(diff))
    weights = ops.softplus(adv_gap)  # smooth positive weighting from advantage gap

    loss = ops.mul(hinge_loss, weights)
    if weight is not None:
        loss = ops.mul(loss, weight)
        return ops.div(ops.sum(loss), ops.sum(weight))
    else:
        return ops.mean(loss)

